/**
 * Staff Guide content: every topic, by role. Shown in the portal (StaffGuideView) and printed
 * to PDF (scripts). Text markup: [[Button]] shows a button label, *bold* shows bold text.
 */
export type GuideRole = 'partner' | 'lawyer' | 'assistant' | 'accounts';
export const ROLES: [GuideRole, string, string][] = [
  ['partner', 'Partner', 'Run files, decide and approve'],
  ['lawyer', 'Lawyer', 'Run your files day to day'],
  ['assistant', 'Assistant', 'Filing, service, diary and clients'],
  ['accounts', 'Accounts', 'Billing, payments and payroll'],
];

/** One step; `sub` are the small points under it (what you will see, what to pick). */
export type Step = string | { t: string; sub?: string[] };
export interface Section {
  /** 'admin' = admins only (any role); 'billing' = Partner / Accounts tabs, or anyone given billing access. */
  id: string; title: string; roles: GuideRole[] | 'all' | 'admin' | 'billing';
  /** Detailed topics: what it is, who does it, and what you need before you start. */
  what?: string; who?: string; before?: string[];
  intro?: string; steps?: Step[];
  /** "If … → do …" for the different situations you may meet. */
  cases?: [string, string][];
  /** "You see … → what it means / what to do" (error messages, missing buttons). */
  stuck?: [string, string][];
  mistakes?: string[];
  tip?: string;
}

